import {
  DEFAULT_ROOM_ID,
  MESSAGE,
  decodeMessage,
  encodeMessage,
  makeInputFrame,
  makePlayerState,
  makeRoomSeed,
  normalizeRoomId,
} from '../public/src/shared/net/protocol.js';
